changeSet.sql:
ALTER TABLE inventory_items
    ADD CONSTRAINT chk_inventory_items_available_nonnegative
        CHECK (available_quantity >= 0);

ALTER TABLE inventory_reservations
    ADD CONSTRAINT chk_inventory_reservations_quantity_positive
        CHECK (quantity > 0);

ALTER TABLE inventory_reservation_operations
    ADD CONSTRAINT chk_inventory_reservation_operations_fingerprint
        CHECK (
            request_fingerprint ~ '^[0-9a-f]{64}$'
    );

ALTER TABLE inventory_reservation_operations
    ADD CONSTRAINT chk_inventory_reservation_operations_status
        CHECK (
            operation_status IN ('IN_PROGRESS', 'COMPLETED')
            );

ALTER TABLE inventory_reservation_operations
    ADD CONSTRAINT chk_inventory_reservation_operations_outcome
        CHECK (
            outcome IS NULL
                OR outcome IN ('RESERVED', 'UNAVAILABLE', 'NOT_FOUND')
            );

ALTER TABLE inventory_reservation_operations
    ADD CONSTRAINT chk_inventory_reservation_operations_completion
        CHECK (
            (
                operation_status = 'IN_PROGRESS'
                    AND outcome IS NULL
                    AND completed_at IS NULL
                )
                OR
            (
                operation_status = 'COMPLETED'
                    AND outcome IS NOT NULL
                    AND completed_at IS NOT NULL
                )
            );

ALTER TABLE inventory_reservation_operations
DROP CONSTRAINT
    chk_inventory_reservation_operations_outcome;

ALTER TABLE inventory_reservation_operations
    ADD CONSTRAINT
        chk_inventory_reservation_operations_outcome
        CHECK (
            outcome IS NULL
                OR outcome IN ('RESERVED', 'UNAVAILABLE')
            );
